    UNION { ?mondo bl:contraindicated_for ?hp . BIND("contraindicated_drug" AS ?rel) }
    UNION { ?mondo bl:related_to ?hp . BIND("related_to" AS ?rel) }
    OPTIONAL { ?hp rdfs:label ?hpLabel }
